{
  "status": "SUPPORTED",
  "task_summary": "Find parts and tools, attach a component to a workbench target, and return the tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "FIXED_TARGET",
        "function": "The specific location on the workbench that needs to be fastened.",
        "required_count": 1
      ,
      "binding_policy": "SHARED",
      "candidate_categories": ["assembly_base", "device", "fixture"],
      "required_properties": ["has_connection_point"]
      },
      {
        "id": "compatible_component",
        "entity_kind": "OBJECT",
        "function": "A part that fits into or attaches to the target to complete the assembly.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["part", "module", "piece", "block"],
        "required_properties": ["fits_target"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "Equipment used to apply force or fasteners to join the component.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "tool"],
        "required_properties": ["can_fasten"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the target is located and tools are returned.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk"],
        "required_properties": ["is_surface"]
      },
      {
        "id": "storage_structure",
        "entity_kind": "REGION",
        "function": "Enclosed areas where components or tools may be hidden.",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": ["cabinet", "drawer"],
        "required_properties": ["is_enclosed", "can_be_opened"]
      }
    ],
    "functional_relations": [
      {
        "id": "suitable_for_fastening",
        "relation": "A compatible component must fit the fastening target.",
        "participant_roles": ["compatible_component", "fastening_target"]
      ,
      "required": true
      },
      {
        "id": "used_for_fastening",
        "relation": "A fastening tool is used to connect the component to the target.",
        "participant_roles": ["fastening_tool", "fastening_target"]
      ,
      "required": true
      },
      {
        "id": "located_in",
        "relation": "Components or tools may be found inside a storage structure.",
        "participant_roles": ["compatible_component", "fastening_tool", "storage_structure"]
      ,
      "required": false
      },
      {
        "id": "returned_to",
        "relation": "Reusable equipment is placed back on the workbench.",
        "participant_roles": ["fastening_tool", "workbench"]
      ,
      "required": false
      }
    ],
    "operation_pairings": [
      {
        "id": "identify_components",
        "operation": "Search storage and inspect visible areas to find compatible components.",
        "participant_roles": ["compatible_component", "storage_structure", "fastening_target"]
      ,
      "operation_count": 1
      },
      {
        "id": "perform_fastening",
        "operation": "Use the tool to attach the component to the target.",
        "participant_roles": ["fastening_tool", "compatible_component", "fastening_target"]
      ,
      "operation_count": 1
      },
      {
        "id": "return_equipment",
        "operation": "Place the fastening tool safely on the workbench.",
        "participant_roles": ["fastening_tool", "workbench"]
      ,
      "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [
        {
          "label": "object_on_desk",
          "visual_description": "Black tray-like object with yellow and blue pieces on the wooden surface."
        }
      ],
      "compatible_component": [
        {
          "label": "yellow_blue_pieces_on_tray",
          "visual_description": "Yellow and blue rectangular blocks sitting on the black tray."
        }
      ],
      "fastening_tool": [],
      "workbench": [
        {
          "label": "wooden_table",
          "visual_description": "Wooden desk with drawers and legs."
        }
      ],
      "storage_structure": [
        {
          "label": "blue_cabinet_behind_desk",
          "visual_description": "Tall blue cabinet standing against the wall behind the desk."
        },
        {
          "label": "drawers_under_desk",
          "visual_description": "Two blue drawers located beneath the wooden table surface."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet_behind_desk",
        "label": "Blue cabinet behind desk",
        "visual_description": "Closed blue cabinet structure.",
        "reason": "Closed structure likely containing parts or tools."
      },
      {
        "id": "drawers_under_desk",
        "label": "Drawers under desk",
        "visual_description": "Closed drawer units under the table.",
        "reason": "Closed structures likely containing parts or tools."
      }
    ],
    "inspection_order": [
      "object_on_desk",
      "blue_cabinet_behind_desk",
      "drawers_under_desk"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
